INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(61929, 1671, 1336, '<td valign="top">focus and lighting need improvement... backdrop is wrinkled.</td>', 'focus and lighting need improvement... backdrop is wrinkled.', '2002-05-20 07:58:00.000000', NULL, 1),
(61930, 1671, 1, '<td valign="top">Seems a little blurry and/or out of focus.  The lighting is way too dark, and from a bad angle so you can''t see the detail in the bad guys'' faces.</td>', 'Seems a little blurry and/or out of focus.  The lighting is way too dark, and from a bad angle so you can''t see the detail in the bad guys'' faces.', '2002-05-20 10:11:00.000000', NULL, 1),
(61931, 1671, 1585, '<td valign="top">Yoda and the ewok are too tall. Still looks like fun.</td>', 'Yoda and the ewok are too tall. Still looks like fun.', '2002-05-20 11:00:00.000000', NULL, 1),
(61932, 1671, 327, '<td valign="top">Your composition could of been better here, and your crop. This is a good idea but could of been better.</td>', 'Your composition could of been better here, and your crop. This is a good idea but could of been better.', '2002-05-20 11:58:00.000000', NULL, 1),
(61933, 1671, 570, '<td valign="top">need to iron that sheet or somethin</td>', 'need to iron that sheet or somethin', '2002-05-20 15:07:00.000000', NULL, 1),
(61934, 1671, 203, '<td valign="top">Seems a little uneven.  Poor Darth.</td>', 'Seems a little uneven.  Poor Darth.', '2002-05-20 17:02:00.000000', NULL, 1),
(61935, 1671, 1569, '<td valign="top">Watch the focus.</td>', 'Watch the focus.', '2002-05-20 17:08:00.000000', NULL, 1),
(61936, 1671, 616, '<td valign="top">no Jar Jar Binks?</td>', 'no Jar Jar Binks?', '2002-05-20 17:35:00.000000', NULL, 1),
(61937, 1671, 509, '<td valign="top">Nice, but it isn''t really a "game" without the title</td>', 'Nice, but it isn''t really a "game" without the title', '2002-05-20 22:30:00.000000', NULL, 1),
(61938, 1671, 1143, '<td valign="top">Cute idea. I don''t like the shot though. The dark background and dark shadows bother me.</td>', 'Cute idea. I don''t like the shot though. The dark background and dark shadows bother me.', '2002-05-21 00:32:00.000000', NULL, 1),
(61939, 1671, 1078, '<td valign="top">The lighting on this one needs some work -- I can see all the rebel faces, but the empire faces are so dark I only know it''s Vader because who else would be a big black blob.  I also think I would have worked on the composition a bit more -- some of the rebel pez dispencers in the back are being covered up by ones in the front.  Same applies, a little, to Boba Fett and Vader.  Overall, though, I just don''t see this as much of a game.</td>', 'The lighting on this one needs some work -- I can see all the rebel faces, but the empire faces are so dark I only know it''s Vader because who else would be a big black blob.  I also think I would have worked on the composition a bit more -- some of the rebel pez dispencers in the back are being covered up by ones in the front.  Same applies, a little, to Boba Fett and Vader.  Overall, though, I just don''t see this as much of a game.', '2002-05-21 11:18:00.000000', NULL, 1),
(61940, 1671, 1446, '<td valign="top">Different concept, but the photo has a feeling of being chopped in half, at least to me</td>', 'Different concept, but the photo has a feeling of being chopped in half, at least to me', '2002-05-21 13:07:00.000000', NULL, 1),
(61941, 1671, 1041, '<td valign="top">Wow, you have quite a collection there.  A little bit more focus and light, and a smooth background (I have found that black cardboard works best for me) would improve the shot IMO.</td>', 'Wow, you have quite a collection there.  A little bit more focus and light, and a smooth background (I have found that black cardboard works best for me) would improve the shot IMO.', '2002-05-21 14:20:00.000000', NULL, 1),
(61942, 1671, 772, '<td valign="top">Interesting concept but the photo just doesn''t appeal to me as a great interpretation of the challenge...</td>', 'Interesting concept but the photo just doesn''t appeal to me as a great interpretation of the challenge...', '2002-05-21 18:08:00.000000', NULL, 1),
(61943, 1671, 1054, '<td valign="top">There are some stray shadows in this shot, and I think it''s a stretch to meet the challenge.</td>', 'There are some stray shadows in this shot, and I think it''s a stretch to meet the challenge.', '2002-05-22 08:42:00.000000', NULL, 1),
(61944, 1671, 1005, '<td valign="top">What is the game?  Bad must be pretty good to face these odds (2 to 1)  Photo 7 Creativity 7 Games 3 total 5</td>', 'What is the game?  Bad must be pretty good to face these odds (2 to 1)  Photo 7 Creativity 7 Games 3 total 5', '2002-05-22 18:28:00.000000', NULL, 1),
(61945, 1671, 842, '<td valign="top">dah,  dah, dah dah dah dah, dah, dah dah, dah... ok -  I realize it doesn''t translate into text very well. but I tried. Are those original? They must be worth a bob or two.</td>', 'dah,  dah, dah dah dah dah, dah, dah dah, dah... ok -  I realize it doesn''t translate into text very well. but I tried. Are those original? They must be worth a bob or two.', '2002-05-22 20:06:00.000000', NULL, 1),
(61946, 1671, 1597, '<td valign="top">to dark of a setting but creative</td>', 'to dark of a setting but creative', '2002-05-22 20:15:00.000000', NULL, 1),
(61947, 1671, 824, '<td valign="top">Cool!</td>', 'Cool!', '2002-05-22 23:13:00.000000', NULL, 1),
(61948, 1671, 1707, '<td valign="top">So how many do you have in your collection?  :)  -NBT</td>', 'So how many do you have in your collection?  :)  -NBT', '2002-05-23 06:16:00.000000', NULL, 1),
(61949, 1671, 1799, '<td valign="top">May the force be with you...</td>', 'May the force be with you...', '2002-05-23 17:16:00.000000', NULL, 1),
(61950, 1671, 1202, '<td valign="top">Get some more light in there to overcome the black background and watch this one snap.   Nice collection.</td>', 'Get some more light in there to overcome the black background and watch this one snap.   Nice collection.', '2002-05-24 21:08:00.000000', NULL, 1),
(61951, 1671, 1135, '<td valign="top">Cool idea but I think it is too dark.</td>', 'Cool idea but I think it is too dark.', '2002-05-25 01:23:00.000000', NULL, 1),
(61952, 1671, 1066, '<td valign="top">Fantastic potential here.  Really.  Just looks rushed.  <br/><br/>If you use a backdrop iron the wrinkles out.  and make your fabric folds subtle.  Table top lighting needs to be more than one source unless you go for a very dramatic shadow effect...<br/><br/>A big pile of pez in all colors with some zany cross lighting would have added to the drama.  Get several flashlights for cheap spotlighting effects and even put colored plastic on the flashlight for some cheap effects.</td>', 'Fantastic potential here.  Really.  Just looks rushed.  If you use a backdrop iron the wrinkles out.  and make your fabric folds subtle.  Table top lighting needs to be more than one source unless you go for a very dramatic shadow effect...A big pile of pez in all colors with some zany cross lighting would have added to the drama.  Get several flashlights for cheap spotlighting effects and even put colored plastic on the flashlight for some cheap effects.', '2002-05-25 11:51:00.000000', NULL, 1),
(61953, 1671, 1361, '<td valign="top">cute.</td>', 'cute.', '2002-05-25 17:46:00.000000', NULL, 1),
(61954, 1671, 428, '<td valign="top">The pez need to be set up so you can see the Ewok behind the Yoda, and the C3PO on the left.  <br/><br/>I think your light is too harsh on the right hand side, the shadows from the "dark side" are too strong, plus there is a shadow on Leia that is cast from Yoda. Try some fill in light on the right.  Your backdrop cloth is too wrinkly.</td>', 'The pez need to be set up so you can see the Ewok behind the Yoda, and the C3PO on the left.  I think your light is too harsh on the right hand side, the shadows from the "dark side" are too strong, plus there is a shadow on Leia that is cast from Yoda. Try some fill in light on the right.  Your backdrop cloth is too wrinkly.', '2002-05-25 20:24:00.000000', NULL, 1),
(61955, 1671, 543, '<td valign="top">The sidelighting isn''t doing much for you here except throwing a shadow on Leia, and Darth''s pretty much disappeared against the black bg.  Shooting from above has emphasized the smallness of the pez dispensers.  There are probably more dramatic, interesting ways to shoot this.</td>', 'The sidelighting isn''t doing much for you here except throwing a shadow on Leia, and Darth''s pretty much disappeared against the black bg.  Shooting from above has emphasized the smallness of the pez dispensers.  There are probably more dramatic, interesting ways to shoot this.', '2002-05-26 02:47:00.000000', NULL, 1),
(61956, 1671, 1808, '<td valign="top">Just need dozens of stormtroopers.</td>', 'Just need dozens of stormtroopers.', '2002-05-26 14:08:00.000000', NULL, 1),
(61957, 1675, 205, '<td valign="top">hell yes<br/></td>', 'hell yes', '2002-05-20 02:08:00.000000', NULL, 1),
(61958, 1675, 1605, '<td valign="top">Eeeeeeeeeeh?</td>', 'Eeeeeeeeeeh?', '2002-05-20 02:21:00.000000', NULL, 1),
(61959, 1675, 772, '<td valign="top">Was this photo framed to intentionally slice off the subject''s face?  I don''t particularly like the crop and I think this is a weak, but not non-existant, relationship to the ''games'' theme.</td>', 'Was this photo framed to intentionally slice off the subject''s face?  I don''t particularly like the crop and I think this is a weak, but not non-existant, relationship to the ''games'' theme.', '2002-05-20 05:51:00.000000', NULL, 1),
(61960, 1675, 1336, '<td valign="top">good idea.  nice photo - very sexy.  her anonymity adds a lot to the picture.</td>', 'good idea.  nice photo - very sexy.  her anonymity adds a lot to the picture.', '2002-05-20 08:00:00.000000', NULL, 1),
(61961, 1675, 47, '<td valign="top">killyourseeeeeeeeelf</td>', 'killyourseeeeeeeeelf', '2002-05-20 09:19:00.000000', NULL, 1),
(61962, 1675, 951, '<td valign="top">Looks like an interesting game!</td>', 'Looks like an interesting game!', '2002-05-20 10:29:00.000000', NULL, 1),
(61963, 1675, 1344, '<td valign="top">uh nice crop</td>', 'uh nice crop', '2002-05-20 11:29:00.000000', NULL, 1),
(61964, 1675, 1041, '<td valign="top">Without the title, "games" wouldn''t exactly have come to mind when viewing the picture.  Also don''t like the cropped head and tip of the shoe.</td>', 'Without the title, "games" wouldn''t exactly have come to mind when viewing the picture.  Also don''t like the cropped head and tip of the shoe.', '2002-05-20 11:36:00.000000', NULL, 1),
(61965, 1675, 885, '<td valign="top">Frightening.</td>', 'Frightening.', '2002-05-20 12:26:00.000000', NULL, 1),
(61966, 1675, 1, '<td valign="top">The baby blue background doesn''t work well with your mischevious subject -- perhaps a bright red background would''ve fit better.</td>', 'The baby blue background doesn''t work well with your mischevious subject -- perhaps a bright red background would''ve fit better.', '2002-05-20 13:41:00.000000', NULL, 1),
(61967, 1675, 587, '<td valign="top">Sorry, this is not the most flattering of poses for this girl. that blue just washes her out.</td>', 'Sorry, this is not the most flattering of poses for this girl. that blue just washes her out.', '2002-05-20 13:58:00.000000', NULL, 1),
(61968, 1675, 327, '<td valign="top">Love the pout, love the shoes, and the make up. Fun shot, fun idea!</td>', 'Love the pout, love the shoes, and the make up. Fun shot, fun idea!', '2002-05-20 14:19:00.000000', NULL, 1),
(61969, 1675, 259, '<td valign="top">crazy</td>', 'crazy', '2002-05-20 14:30:00.000000', NULL, 1),
(61970, 1675, 862, '<td valign="top">The light blue background seems at odds with your suggestive theme.<br/></td>', 'The light blue background seems at odds with your suggestive theme.', '2002-05-20 14:44:00.000000', NULL, 1),
(61971, 1675, 1024, '<td valign="top">You will probably get high marks for this from the guys, but being a woman, it does nothing for me.  I would like it better if I could see her eyes</td>', 'You will probably get high marks for this from the guys, but being a woman, it does nothing for me.  I would like it better if I could see her eyes', '2002-05-20 16:12:00.000000', NULL, 1),
(61972, 1675, 616, '<td valign="top">A different backdrop would have fit better. Maybe a white or black. One of the shoes is cut off. It seems there was some room on the other side to crop it. I like this...it''s a very hott idea.</td>', 'A different backdrop would have fit better. Maybe a white or black. One of the shoes is cut off. It seems there was some room on the other side to crop it. I like this...it''s a very hott idea.', '2002-05-20 17:39:00.000000', NULL, 1),
(61973, 1675, 1696, '<td valign="top">This seems like a ploy for points by trying to appeal to our prurient interests. The title makes it about a game, but other than that, I don''t see the connection, unless you mean some sort of mind game. In that case, you could take a picture of her brains stem and not her crotch.</td>', 'This seems like a ploy for points by trying to appeal to our prurient interests. The title makes it about a game, but other than that, I don''t see the connection, unless you mean some sort of mind game. In that case, you could take a picture of her brains stem and not her crotch.', '2002-05-20 18:07:00.000000', NULL, 1),
(61974, 1675, 1446, '<td valign="top">I am sure it was for the sake of art........but I prefer my pictures without the heads cut off....</td>', 'I am sure it was for the sake of art........but I prefer my pictures without the heads cut off....', '2002-05-20 19:21:00.000000', NULL, 1),
(61975, 1675, 543, '<td valign="top">Well lit, and sexy.  What more do I want?  Well...  it looks like privacy/anonymity issues with the model hurt the composition - much better to show us the rest of her face or, if that wasn''t possible, to square crop in order to lose the empty blue space.  Given her apparent reluctance and the site rules, though, all I can fault you with is chopping off the end of her shoe.  Getting really picky, it would be nice if she were sitting up a little straighter, and this pose gives a less-than-wonderful calf droop on her near leg.  I wanna play, anyway.</td>', 'Well lit, and sexy.  What more do I want?  Well...  it looks like privacy/anonymity issues with the model hurt the composition - much better to show us the rest of her face or, if that wasn''t possible, to square crop in order to lose the empty blue space.  Given her apparent reluctance and the site rules, though, all I can fault you with is chopping off the end of her shoe.  Getting really picky, it would be nice if she were sitting up a little straighter, and this pose gives a less-than-wonderful calf droop on her near leg.  I wanna play, anyway.', '2002-05-21 11:13:00.000000', NULL, 1),
(61976, 1675, 1009, '<td valign="top">Grrr....</td>', 'Grrr....', '2002-05-21 17:17:00.000000', NULL, 1),
(61977, 1675, 878, '<td valign="top">Good shot and good subject as well.  Very original.</td>', 'Good shot and good subject as well.  Very original.', '2002-05-21 18:46:00.000000', NULL, 1),
(61978, 1675, 1175, '<td valign="top">Clever idea for a game.  Unfortunately I did not find your model, or perhaps the position she was in very attractive.  For a picture that is trying to represent a more risque lifestyle and subject the lightblue sort of kills it.  You should have gone with black or a deep red.</td>', 'Clever idea for a game.  Unfortunately I did not find your model, or perhaps the position she was in very attractive.  For a picture that is trying to represent a more risque lifestyle and subject the lightblue sort of kills it.  You should have gone with black or a deep red.', '2002-05-21 19:21:00.000000', NULL, 1),
(61979, 1675, 1597, '<td valign="top">crsip, and creative</td>', 'crsip, and creative', '2002-05-21 21:01:00.000000', NULL, 1),
(61980, 1675, 301, '<td valign="top">the blue background isn''t really the most pleasing, and the large amount of it at the bottom probably isn''t needed.  Tip of the shoe has been cropped, and her facial expression isn''t enough to grab my interest.  Seeing as you were going for the ''sex sells'' concept, what might have worked is if you had a guy dressed as a burglar lying face down, arms behind his back ... and the girl over him about to put the cuffs on.</td>', 'the blue background isn''t really the most pleasing, and the large amount of it at the bottom probably isn''t needed.  Tip of the shoe has been cropped, and her facial expression isn''t enough to grab my interest.  Seeing as you were going for the ''sex sells'' concept, what might have worked is if you had a guy dressed as a burglar lying face down, arms behind his back ... and the girl over him about to put the cuffs on.', '2002-05-22 03:47:00.000000', NULL, 1),
(61981, 1675, 1037, '<td valign="top">Very sleazy. There isn''t much more than cheap titillation in this photo, so as a woman it doesn''t appeal to me. And those shoes are horrible.</td>', 'Very sleazy. There isn''t much more than cheap titillation in this photo, so as a woman it doesn''t appeal to me. And those shoes are horrible.', '2002-05-22 08:56:00.000000', NULL, 1),
(61982, 1675, 1005, '<td valign="top">Nasty!  Photo 10 Creativity 9 Games 8 total 9  (I like it, but you''re gonna lose)</td>', 'Nasty!  Photo 10 Creativity 9 Games 8 total 9  (I like it, but you''re gonna lose)', '2002-05-22 19:04:00.000000', NULL, 1),
(61983, 1675, 842, '<td valign="top">it''s an interesting shot, but I think it would have been better in b&amp;w or perhaps a darker back drop. I think the aqua clashes with the skin tone a bit.</td>', 'it''s an interesting shot, but I think it would have been better in b&w or perhaps a darker back drop. I think the aqua clashes with the skin tone a bit.', '2002-05-22 20:12:00.000000', NULL, 1),
(61984, 1675, 573, '<td valign="top">My mother-in-law puts the point of interest in the center of the frame also.</td>', 'My mother-in-law puts the point of interest in the center of the frame also.', '2002-05-23 12:23:00.000000', NULL, 1),
(61985, 1675, 332, '<td valign="top">What the... ???</td>', 'What the... ???', '2002-05-23 17:49:00.000000', NULL, 1),
(61986, 1675, 757, '<td valign="top">If you hadn''t cropped off the top of the head I would have given this photo a 10. Unfortunately that spoiled. Still a very good photo and a great play on the "games" theme.</td>', 'If you hadn''t cropped off the top of the head I would have given this photo a 10. Unfortunately that spoiled. Still a very good photo and a great play on the "games" theme.', '2002-05-23 19:48:00.000000', NULL, 1),
(61987, 1675, 811, '<td valign="top">Cutting off the top of her head lends an air of mystery to this shot.  A different color for the background, I think, would''ve been more characteristic.  (Say yellow or orange, maybe read instead of a cool blue?)</td>', 'Cutting off the top of her head lends an air of mystery to this shot.  A different color for the background, I think, would''ve been more characteristic.  (Say yellow or orange, maybe read instead of a cool blue?)', '2002-05-23 19:57:00.000000', NULL, 1),
(61988, 1675, 1679, '<td valign="top">I understand you probably wanted to hide your model''s identity. However, headless photos of people are not the best, unless they are close-ups, where you can emphasise on specifica characteristics of the face.<br/>Still, if your model insister that you did not post her face on the web, you could have cropped out the lower third of the photo. It adds nothing to the photo. Just emptiness.<br/>Also, (just minor details though), the tip of her right shoe is trimmed and your reflection can be seen on that shoe. Cloned out maybe?<br/>Lighting is very even and therefore photo lacks contrast.</td>', 'I understand you probably wanted to hide your model''s identity. However, headless photos of people are not the best, unless they are close-ups, where you can emphasise on specifica characteristics of the face.Still, if your model insister that you did not post her face on the web, you could have cropped out the lower third of the photo. It adds nothing to the photo. Just emptiness.Also, (just minor details though), the tip of her right shoe is trimmed and your reflection can be seen on that shoe. Cloned out maybe?Lighting is very even and therefore photo lacks contrast.', '2002-05-25 09:01:00.000000', NULL, 1),
(61989, 1675, 1066, '<td valign="top">Cant make my mind up if cutting her head off works or not.  Maybe if you would have found a black party mask, black hankercheif with holes cut in it ala Zorro you could have gotten here head in while maintaining mystery.<br/><br/>I just think the combo of cutting her head off and too much blue foreground throws me off a bit.  But  I think this is well photographed and a good idea.</td>', 'Cant make my mind up if cutting her head off works or not.  Maybe if you would have found a black party mask, black hankercheif with holes cut in it ala Zorro you could have gotten here head in while maintaining mystery.I just think the combo of cutting her head off and too much blue foreground throws me off a bit.  But  I think this is well photographed and a good idea.', '2002-05-25 11:22:00.000000', NULL, 1),
(61990, 1675, 255, '<td valign="top">i think i would have gone all the way here and moved the camera angle to cut more off the bottom and put her whole face in the frame!<br/>otherwise i like it.<br/></td>', 'i think i would have gone all the way here and moved the camera angle to cut more off the bottom and put her whole face in the frame!otherwise i like it.', '2002-05-25 14:30:00.000000', NULL, 1),
(61991, 1675, 527, '<td valign="top">This is really good. However, I think I would not have cropped out the tip of the shoe and there may be a little too much space on the bottom.</td>', 'This is really good. However, I think I would not have cropped out the tip of the shoe and there may be a little too much space on the bottom.', '2002-05-26 01:51:00.000000', NULL, 1),
(61992, 1675, 554, '<td valign="top">why did you cut off her head and shoe?</td>', 'why did you cut off her head and shoe?', '2002-05-26 08:18:00.000000', NULL, 1),
(61993, 1676, 205, '<td valign="top">thanks for making me hungry</td>', 'thanks for making me hungry', '2002-05-20 02:00:00.000000', NULL, 1),
(61994, 1676, 1379, '<td valign="top">I love games like this....</td>', 'I love games like this....', '2002-05-20 14:02:00.000000', NULL, 1),
(61995, 1676, 327, '<td valign="top">Fun idea. Good spirit of the challenge. Clean clear shot.</td>', 'Fun idea. Good spirit of the challenge. Clean clear shot.', '2002-05-20 14:21:00.000000', NULL, 1),
(61996, 1676, 259, '<td valign="top">we''ll see if you still call it a win when you are at the dentist.</td>', 'we''ll see if you still call it a win when you are at the dentist.', '2002-05-20 14:32:00.000000', NULL, 1),
