(61998, 1676, 1750, '<td valign="top">Cute juxtaposition. Personal taste: the child playing the game completes the story.</td>', 'Cute juxtaposition. Personal taste: the child playing the game completes the story.', '2002-05-20 15:10:00.000000', NULL, 1),
(61999, 1676, 1446, '<td valign="top">Changing my vote on this one already.  I like the use of food in this shot.  The way it is set up it keeps bringing my eye around and around and around. Nice focus...ok thats it.......I need cookies and milk NOW!</td>', 'Changing my vote on this one already.  I like the use of food in this shot.  The way it is set up it keeps bringing my eye around and around and around. Nice focus...ok thats it.......I need cookies and milk NOW!', '2002-05-20 16:12:00.000000', NULL, 1),
