(62001, 1676, 436, '<td valign="top">great concept</td>', 'great concept', '2002-05-21 08:30:00.000000', NULL, 1),
(62002, 1676, 1455, '<td valign="top">This is my kind of game..........</td>', 'This is my kind of game..........', '2002-05-21 09:36:00.000000', NULL, 1),
