(62096, 1678, 1005, '<td valign="top">Good action for chess!  Some harse glare, filters might have helped here.  Photo 8 Creativity 6 Games 7 total 7</td>', 'Good action for chess!  Some harse glare, filters might have helped here.  Photo 8 Creativity 6 Games 7 total 7', '2002-05-22 18:14:00.000000', NULL, 1),
