(62098, 1678, 1169, '<td valign="top">yes</td>', 'yes', '2002-05-22 22:55:00.000000', NULL, 1),
(62099, 1678, 573, '<td valign="top">The intensity is electric!  My eye is drawen directly to his face that is telling me about the concentration being spent on the game.</td>', 'The intensity is electric!  My eye is drawen directly to his face that is telling me about the concentration being spent on the game.', '2002-05-23 10:29:00.000000', NULL, 1),
(62100, 1678, 193, '<td valign="top">I love the way you captured the concentration of this man!  Too bad you couldn''t oust the guy in grey...</td>', 'I love the way you captured the concentration of this man!  Too bad you couldn''t oust the guy in grey...', '2002-05-23 15:14:00.000000', NULL, 1),
(62101, 1678, 1793, '<td valign="top">ah, the concentration of a chess player.. great moment captured.</td>', 'ah, the concentration of a chess player.. great moment captured.', '2002-05-23 22:11:00.000000', NULL, 1),
(62102, 1678, 1041, '<td valign="top">Great shot, love it that they are ACTUALLY playing, the angle is great.  The whole photo looks just a tad out of focus though.</td>', 'Great shot, love it that they are ACTUALLY playing, the angle is great.  The whole photo looks just a tad out of focus though.', '2002-05-24 15:20:00.000000', NULL, 1),
(62103, 1678, 1202, '<td valign="top">I think the character of the man robs from the main game subject.   Or is that the game?   Rare action shot of chess.   Good job.</td>', 'I think the character of the man robs from the main game subject.   Or is that the game?   Rare action shot of chess.   Good job.', '2002-05-24 21:22:00.000000', NULL, 1),
(62104, 1678, 689, '<td valign="top">The hand and the board are a little overexposed ...</td>', 'The hand and the board are a little overexposed ...', '2002-05-24 22:36:00.000000', NULL, 1),
(62105, 1678, 1135, '<td valign="top">Too bad the table is blown. Nice composition.</td>', 'Too bad the table is blown. Nice composition.', '2002-05-25 01:32:00.000000', NULL, 1),
(62106, 1678, 1128, '<td valign="top">Interesting shot.  I like the expression--intense.</td>', 'Interesting shot.  I like the expression--intense.', '2002-05-25 09:15:00.000000', NULL, 1),
(62107, 1678, 1066, '<td valign="top">My favorite people shot of the week (cept for mine :-)<br/><br/>Love the guy in the hat, glasses and coat.  He is stylish whether he intended to be or not and makes the shot..which I am sure is why you took his photo:-)</td>', 'My favorite people shot of the week (cept for mine :-)Love the guy in the hat, glasses and coat.  He is stylish whether he intended to be or not and makes the shot..which I am sure is why you took his photo:-)', '2002-05-25 11:30:00.000000', NULL, 1),
(62108, 1678, 280, '<td valign="top">The quality of the photo doesnt seem very good, however the compositon of the shot is good, I like the guys arm hanging over the board.</td>', 'The quality of the photo doesnt seem very good, however the compositon of the shot is good, I like the guys arm hanging over the board.', '2002-05-25 17:19:00.000000', NULL, 1),
(62109, 1678, 1031, '<td valign="top">On my monitor the highlights are a little blown-out...</td>', 'On my monitor the highlights are a little blown-out...', '2002-05-25 18:44:00.000000', NULL, 1),
(62110, 1678, 637, '<td valign="top">For me, nothing beats live action in this challenge.</td>', 'For me, nothing beats live action in this challenge.', '2002-05-26 01:18:00.000000', NULL, 1),
(62111, 1678, 1061, '<td valign="top">Good subjectamundo</td>', 'Good subjectamundo', '2002-05-26 04:03:00.000000', NULL, 1),
(62112, 1678, 1, '<td valign="top">Nicely caught, I wish the light wasn''t so harsh on the chess board though.</td>', 'Nicely caught, I wish the light wasn''t so harsh on the chess board though.', '2002-05-26 09:41:00.000000', NULL, 1),
(62113, 1678, 543, '<td valign="top">Some blowout on his hand and the pieces, but a great capture of the indecisive moment.</td>', 'Some blowout on his hand and the pieces, but a great capture of the indecisive moment.', '2002-05-27 00:04:00.000000', NULL, 1),
(62114, 1678, 47, '<td valign="top">i still think this was the best picture.</td>', 'i still think this was the best picture.', '2002-05-27 09:28:00.000000', NULL, 0),
(62115, 1680, 47, '<td valign="top">last i checked, this is not how poker is played.</td>', 'last i checked, this is not how poker is played.', '2002-05-20 09:05:00.000000', NULL, 1),
(62116, 1680, 1379, '<td valign="top">Nice colors!</td>', 'Nice colors!', '2002-05-20 10:34:00.000000', NULL, 1),
(62117, 1680, 1041, '<td valign="top">This looks oversharpened, and also doesn''t invoke "poker" with me w/out reading the title.  Maybe a hand of cards and the money in the pot in the middle would''ve been better.</td>', 'This looks oversharpened, and also doesn''t invoke "poker" with me w/out reading the title.  Maybe a hand of cards and the money in the pot in the middle would''ve been better.', '2002-05-20 11:41:00.000000', NULL, 1),
(62118, 1680, 1, '<td valign="top">Seems too scattered/cluttered to have any large effect.  I think a nice stack of cards, a nice stack of cash, and a few stacks of change would''ve have a larger effect.</td>', 'Seems too scattered/cluttered to have any large effect.  I think a nice stack of cards, a nice stack of cash, and a few stacks of change would''ve have a larger effect.', '2002-05-20 13:49:00.000000', NULL, 1),
(62119, 1680, 327, '<td valign="top">This is a fine idea and a good try. I would of liked  the cards more disorganized, a little too staged here. Money [paper] is all right side up. It''s not bad at all!</td>', 'This is a fine idea and a good try. I would of liked  the cards more disorganized, a little too staged here. Money [paper] is all right side up. It''s not bad at all!', '2002-05-20 14:25:00.000000', NULL, 1),
(62120, 1680, 203, '<td valign="top">Did you make that $5 on your HP?</td>', 'Did you make that $5 on your HP?', '2002-05-20 16:57:00.000000', NULL, 1),
(62121, 1680, 1756, '<td valign="top">Bye Abe. :( Goodjob</td>', 'Bye Abe. :( Goodjob', '2002-05-20 17:53:00.000000', NULL, 1),
(62122, 1680, 1446, '<td valign="top">The money seems out of foucs on my screen.</td>', 'The money seems out of foucs on my screen.', '2002-05-21 13:05:00.000000', NULL, 1),
(62123, 1680, 1078, '<td valign="top">I see the cards and money, but I have to admit I wouldn''t immediately think Poker without the title -- gambling maybe.  There are an awful lot of compression artifacts -- and I notice your file size is about half what it could be.  You might want to save at a higher resolution.  The focus on this could also be a little sharper, and the color seems to have something of a green tint -- as if you shot under florescent lighting.  Try a levels fix in your image editing program.</td>', 'I see the cards and money, but I have to admit I wouldn''t immediately think Poker without the title -- gambling maybe.  There are an awful lot of compression artifacts -- and I notice your file size is about half what it could be.  You might want to save at a higher resolution.  The focus on this could also be a little sharper, and the color seems to have something of a green tint -- as if you shot under florescent lighting.  Try a levels fix in your image editing program.', '2002-05-21 15:26:00.000000', NULL, 1),
(62124, 1680, 1009, '<td valign="top">Nice pic... a little off focus though? Or intentional? Nice  eitherway...</td>', 'Nice pic... a little off focus though? Or intentional? Nice  eitherway...', '2002-05-21 17:06:00.000000', NULL, 1),
(62125, 1680, 441, '<td valign="top">focus looks a little out, good colourful subject</td>', 'focus looks a little out, good colourful subject', '2002-05-21 17:46:00.000000', NULL, 1),
(62126, 1680, 587, '<td valign="top">Perhaps if this looked like a poker game it would have sold this a little better, sorry just seems somewhat unorganized.</td>', 'Perhaps if this looked like a poker game it would have sold this a little better, sorry just seems somewhat unorganized.', '2002-05-21 18:01:00.000000', NULL, 1),
(62127, 1680, 1175, '<td valign="top">Your pictures seems to be a tad out of focus and it looks like maybe you had too much jpeg compression going on.  Your file is only 80+kb and you have a maximum of 150kb to work with.  Try saving this at a higher resolution.  The picture also seems to be a bit to crazy.  There is too much going on.  I would have prefered if you would have narrowed your subject down, maybe putting the cards in a stack with a pile of money next to it.</td>', 'Your pictures seems to be a tad out of focus and it looks like maybe you had too much jpeg compression going on.  Your file is only 80+kb and you have a maximum of 150kb to work with.  Try saving this at a higher resolution.  The picture also seems to be a bit to crazy.  There is too much going on.  I would have prefered if you would have narrowed your subject down, maybe putting the cards in a stack with a pile of money next to it.', '2002-05-21 19:07:00.000000', NULL, 1),
(62128, 1680, 878, '<td valign="top">I think this would of worked better if it showed an actual poker hand with money next to it to make it look more like the game play of poker.</td>', 'I think this would of worked better if it showed an actual poker hand with money next to it to make it look more like the game play of poker.', '2002-05-22 15:56:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(62129, 1680, 772, '<td valign="top">I think some shinier coins may have improved the impact here... I would also like it a little more photographed from an angle rather than from directly overhead... good job!</td>', 'I think some shinier coins may have improved the impact here... I would also like it a little more photographed from an angle rather than from directly overhead... good job!', '2002-05-22 20:32:00.000000', NULL, 1),
(62130, 1680, 824, '<td valign="top">Nice shot.</td>', 'Nice shot.', '2002-05-22 22:56:00.000000', NULL, 1),
(62131, 1680, 1336, '<td valign="top">out of focus.  this photo is rather boring, i dont think the cards make a good background and the money on top just doesnt do anything for me.  a better idea might have been a pile of money on a table with a hand of cards in view.</td>', 'out of focus.  this photo is rather boring, i dont think the cards make a good background and the money on top just doesnt do anything for me.  a better idea might have been a pile of money on a table with a hand of cards in view.', '2002-05-23 09:36:00.000000', NULL, 1),
(62132, 1680, 1597, '<td valign="top">to out of focus it makes it hard to look at I would have tried a better contrast of colors..but great effort</td>', 'to out of focus it makes it hard to look at I would have tried a better contrast of colors..but great effort', '2002-05-23 22:58:00.000000', NULL, 1),
(62133, 1680, 748, '<td valign="top">Focus could have been better.</td>', 'Focus could have been better.', '2002-05-24 10:56:00.000000', NULL, 1),
(62134, 1680, 244, '<td valign="top">Interesting idea, too many cards on the table tough, would have liked it better with the money in a pile and maybe a hand or two of cards being the only showed.  Also the "soft" focus is a little distracting.</td>', 'Interesting idea, too many cards on the table tough, would have liked it better with the money in a pile and maybe a hand or two of cards being the only showed.  Also the "soft" focus is a little distracting.', '2002-05-24 23:37:00.000000', NULL, 1),
(62135, 1680, 428, '<td valign="top">too blurry</td>', 'too blurry', '2002-05-25 20:58:00.000000', NULL, 1),
(62136, 1680, 637, '<td valign="top">Makes me very nostalgic for my regular Wednesday night poker game in Queens, NY, many years ago.  Great capture.  Love the cropping.</td>', 'Makes me very nostalgic for my regular Wednesday night poker game in Queens, NY, many years ago.  Great capture.  Love the cropping.', '2002-05-26 01:07:00.000000', NULL, 1),
(62137, 1680, 527, '<td valign="top">I like the business of this scene, it fits. I think it could use more contrasty lighting with darker shadows.</td>', 'I like the business of this scene, it fits. I think it could use more contrasty lighting with darker shadows.', '2002-05-26 02:42:00.000000', NULL, 1),
(62138, 1680, 1849, '<td valign="top">focus?</td>', 'focus?', '2002-05-26 12:19:00.000000', NULL, 1),
(62139, 1681, 1379, '<td valign="top">I LOVE THIS GAME!</td>', 'I LOVE THIS GAME!', '2002-05-20 07:18:00.000000', NULL, 1),
(62140, 1681, 1, '<td valign="top">The red cast isn''t very appealing, and I think you cropped the top too much, as the peg is cut off.</td>', 'The red cast isn''t very appealing, and I think you cropped the top too much, as the peg is cut off.', '2002-05-20 07:57:00.000000', NULL, 1),
(62141, 1681, 587, '<td valign="top">sorry, don''t like the coloring on this</td>', 'sorry, don''t like the coloring on this', '2002-05-20 12:44:00.000000', NULL, 1),
(62142, 1681, 1446, '<td valign="top">Seems out of focus on my monitor.  But keep on trying and getting better.  I like the red!</td>', 'Seems out of focus on my monitor.  But keep on trying and getting better.  I like the red!', '2002-05-20 13:28:00.000000', NULL, 1),
(62143, 1681, 327, '<td valign="top">Loud game, fun idea. Composition needed some help, part of the boats stack is cut off and OOF. All in all fun shot, good idea.</td>', 'Loud game, fun idea. Composition needed some help, part of the boats stack is cut off and OOF. All in all fun shot, good idea.', '2002-05-20 14:23:00.000000', NULL, 1),
(62144, 1681, 1175, '<td valign="top">whoa hold down that red.  Just a bit too much.</td>', 'whoa hold down that red.  Just a bit too much.', '2002-05-20 14:42:00.000000', NULL, 1),
(62145, 1681, 1041, '<td valign="top">I''m assuming you were going for the red blurred look?  IMO, it doesn''t work all that well, unfortunately.</td>', 'I''m assuming you were going for the red blurred look?  IMO, it doesn''t work all that well, unfortunately.', '2002-05-20 14:51:00.000000', NULL, 1),
(62146, 1681, 1569, '<td valign="top">The red is too much.</td>', 'The red is too much.', '2002-05-20 17:34:00.000000', NULL, 1),
(62147, 1681, 430, '<td valign="top">this photo is pretty bad! you should have adjusted the levels before submitting. also, the red light is a little too powerful for the photo.</td>', 'this photo is pretty bad! you should have adjusted the levels before submitting. also, the red light is a little too powerful for the photo.', '2002-05-20 21:58:00.000000', NULL, 1),
(62148, 1681, 1078, '<td valign="top">Wow, very red.  Was this to give the feel of an explosion?  Since this boat has been destroyed, and the one in the background at least hit, I think I would have added at least a couple of misses to the shot to add some realism.  I also have to admit, I don''t think the red works.  This is a clever idea for a macro, and I think that alone could have carried it off -- especially if you moved one or two of the ships so all you saw around them was "water" and some misses.  Finally, the focus seems a little soft -- either better focus taking the shot (preferable) or at least some sharpening during post-processing.</td>', 'Wow, very red.  Was this to give the feel of an explosion?  Since this boat has been destroyed, and the one in the background at least hit, I think I would have added at least a couple of misses to the shot to add some realism.  I also have to admit, I don''t think the red works.  This is a clever idea for a macro, and I think that alone could have carried it off -- especially if you moved one or two of the ships so all you saw around them was "water" and some misses.  Finally, the focus seems a little soft -- either better focus taking the shot (preferable) or at least some sharpening during post-processing.', '2002-05-21 11:35:00.000000', NULL, 1),
(62149, 1681, 1024, '<td valign="top">I like the composition of this photograph, and the use of red is very compelling.  I do believe that the subject should have been in focus a little more.</td>', 'I like the composition of this photograph, and the use of red is very compelling.  I do believe that the subject should have been in focus a little more.', '2002-05-21 12:10:00.000000', NULL, 1),
(62150, 1681, 1360, '<td valign="top">Is this image supposed to be very red?  Either way, the red overwhelms the image.</td>', 'Is this image supposed to be very red?  Either way, the red overwhelms the image.', '2002-05-21 13:03:00.000000', NULL, 1),
(62151, 1681, 1031, '<td valign="top">I''d probably add some contrast and run the Unsharp Mask filter. OR...I might have tried to change the overall coloring to a bluish-green to make it look as though it was taken underwater.</td>', 'I''d probably add some contrast and run the Unsharp Mask filter. OR...I might have tried to change the overall coloring to a bluish-green to make it look as though it was taken underwater.', '2002-05-21 19:39:00.000000', NULL, 1),
(62152, 1681, 741, '<td valign="top">Not sure the red cast really works</td>', 'Not sure the red cast really works', '2002-05-22 11:48:00.000000', NULL, 1),
(62153, 1681, 772, '<td valign="top">Interesting photo but I don''t particluarly like the red glow.. I know that this is relaying the sense of the ''sinking'' ship but it just isn''t grabbing me...</td>', 'Interesting photo but I don''t particluarly like the red glow.. I know that this is relaying the sense of the ''sinking'' ship but it just isn''t grabbing me...', '2002-05-22 20:24:00.000000', NULL, 1),
(62154, 1681, 1707, '<td valign="top">red for distress...good idea!  -NBT</td>', 'red for distress...good idea!  -NBT', '2002-05-23 06:30:00.000000', NULL, 1),
(62155, 1681, 1336, '<td valign="top">i didnt like this photo... maybe it''s just too red for my taste.  also, it seems to be out of focus and the framing could be better.</td>', 'i didnt like this photo... maybe it''s just too red for my taste.  also, it seems to be out of focus and the framing could be better.', '2002-05-23 09:33:00.000000', NULL, 1),
(62156, 1681, 1005, '<td valign="top">(It''s an aircraft carrier)</td>', '(It''s an aircraft carrier)', '2002-05-23 13:05:00.000000', NULL, 1),
(62157, 1681, 757, '<td valign="top">Way too red</td>', 'Way too red', '2002-05-23 19:49:00.000000', NULL, 1),
(62158, 1681, 1597, '<td valign="top">This would have been better with natural colors</td>', 'This would have been better with natural colors', '2002-05-23 22:26:00.000000', NULL, 1),
(62159, 1681, 1814, '<td valign="top">Intresting , but fuzzy image</td>', 'Intresting , but fuzzy image', '2002-05-24 07:36:00.000000', NULL, 1),
(62160, 1681, 244, '<td valign="top">I like the red in the image to kinad give that red alert feel on a battle bridge, wish the shot was a little better focused and not quite so grainy.</td>', 'I like the red in the image to kinad give that red alert feel on a battle bridge, wish the shot was a little better focused and not quite so grainy.', '2002-05-24 23:34:00.000000', NULL, 1),
(62161, 1681, 1135, '<td valign="top">I like the red saturation, feels like I''m in the Sub.</td>', 'I like the red saturation, feels like I''m in the Sub.', '2002-05-25 01:38:00.000000', NULL, 1),
(62162, 1681, 1066, '<td valign="top">I can see where you are going with the red lighting effect but its very hard to use red lighting in a home environment and get the drama you see on TV.  The all red lighting you see on many movies is actually supplemtned VERY heavy with white light and highlighted with red.  <br/><br/>Good way to get red light real well is with flashlights.  Get 2, use one with a white bulb and one with a red bulb or red plastic over the lense and play with the various angles.  This is light cheap stage lighitng.</td>', 'I can see where you are going with the red lighting effect but its very hard to use red lighting in a home environment and get the drama you see on TV.  The all red lighting you see on many movies is actually supplemtned VERY heavy with white light and highlighted with red.  Good way to get red light real well is with flashlights.  Get 2, use one with a white bulb and one with a red bulb or red plastic over the lense and play with the various angles.  This is light cheap stage lighitng.', '2002-05-25 11:55:00.000000', NULL, 1),
(62163, 1681, 428, '<td valign="top">Did you mean for this to be all red?</td>', 'Did you mean for this to be all red?', '2002-05-25 21:17:00.000000', NULL, 1),
(62164, 1681, 527, '<td valign="top">The red just doesn''t work for me and it looks blurry.</td>', 'The red just doesn''t work for me and it looks blurry.', '2002-05-26 02:04:00.000000', NULL, 1),
(62165, 1681, 543, '<td valign="top">Macro, IMO, ought to be sharper than this.  The center of the board rather than a corner might have been more effective, as well.  Why red?</td>', 'Macro, IMO, ought to be sharper than this.  The center of the board rather than a corner might have been more effective, as well.  Why red?', '2002-05-26 03:24:00.000000', NULL, 1),
(62166, 1681, 811, '<td valign="top">The red tint gives the impression of being on a boat/sub when all of the red warning lights are going off.  If that was intentional -- good job, if not, well . ..</td>', 'The red tint gives the impression of being on a boat/sub when all of the red warning lights are going off.  If that was intentional -- good job, if not, well . ..', '2002-05-27 00:53:00.000000', NULL, 1),
(62167, 1685, 1037, '<td valign="top">This photo is gorgeous. The female torso is one of my favourite things, especially seeing as I do bellydancing as a hobby :). This is subtly erotic and beautifully photographed, if maybe a bit too deliberately posed. 10 from me.</td>', 'This photo is gorgeous. The female torso is one of my favourite things, especially seeing as I do bellydancing as a hobby :). This is subtly erotic and beautifully photographed, if maybe a bit too deliberately posed. 10 from me.', '2002-05-20 04:32:00.000000', NULL, 1),
(62168, 1685, 1336, '<td valign="top">beautiful.  great idea and well shot.</td>', 'beautiful.  great idea and well shot.', '2002-05-20 07:44:00.000000', NULL, 1),
