(62361, 1696, 724, '<td valign="top">Don''t you hate light poles.  No deduction for them though, great timing on this shot.</td>', 'Don''t you hate light poles.  No deduction for them though, great timing on this shot.', '2002-05-20 14:42:00.000000', NULL, 1),
(62362, 1696, 1175, '<td valign="top">This is a cool picture but unfortunately it suffers from lack of post processing.  Try to get your hands on a copy of a decent photo editing program.  Then play with brightness and contrast.  Just opening this photo up in Photoshop and doing auto levels and auto contrast does wonders for the image.</td>', 'This is a cool picture but unfortunately it suffers from lack of post processing.  Try to get your hands on a copy of a decent photo editing program.  Then play with brightness and contrast.  Just opening this photo up in Photoshop and doing auto levels and auto contrast does wonders for the image.', '2002-05-20 15:07:00.000000', NULL, 1),
(62363, 1696, 570, '<td valign="top">good motion shot</td>', 'good motion shot', '2002-05-20 15:09:00.000000', NULL, 1),
(62364, 1696, 714, '<td valign="top">Wow...your dog looks scary!  Look at those teeth.  What a cool picture.</td>', 'Wow...your dog looks scary!  Look at those teeth.  What a cool picture.', '2002-05-20 15:31:00.000000', NULL, 1),
