(62381, 1696, 1202, '<td valign="top">This is a fun photo, too bad about the vertical lines caused by the two poles.   I like it a lot though.</td>', 'This is a fun photo, too bad about the vertical lines caused by the two poles.   I like it a lot though.', '2002-05-24 19:20:00.000000', NULL, 1),
(62382, 1696, 661, '<td valign="top">Nice stop motion.</td>', 'Nice stop motion.', '2002-05-24 23:29:00.000000', NULL, 1),
(62383, 1696, 543, '<td valign="top">Nice catch, both of you.  Did you throw the frisbee, too? The timing and catch of the dog''s shadow are great, and it looks like the perfect shutter speed for this - just a little blur in the boving fur to show motion, but the eye (with highlight!), teeth, etc. all nice and sharp.  The flagpoles detract, and there''s a yellow cast.  LIke many photos here, this could use a positive gamma adjustment to bring out a little detail in the shadows.  With a little editing, this would make a good one for your wall.</td>', 'Nice catch, both of you.  Did you throw the frisbee, too? The timing and catch of the dog''s shadow are great, and it looks like the perfect shutter speed for this - just a little blur in the boving fur to show motion, but the eye (with highlight!), teeth, etc. all nice and sharp.  The flagpoles detract, and there''s a yellow cast.  LIke many photos here, this could use a positive gamma adjustment to bring out a little detail in the shadows.  With a little editing, this would make a good one for your wall.', '2002-05-25 02:37:00.000000', NULL, 1),
(62384, 1696, 441, '<td valign="top">well caught, portrait would have helped without posts but always not possible when catching the moment like this one!</td>', 'well caught, portrait would have helped without posts but always not possible when catching the moment like this one!', '2002-05-25 15:30:00.000000', NULL, 1),
(62385, 1696, 527, '<td valign="top">I think this could benefit by adjusting levels or contrast so the white part of the dog would pop more.</td>', 'I think this could benefit by adjusting levels or contrast so the white part of the dog would pop more.', '2002-05-26 02:02:00.000000', NULL, 1),
(62386, 1696, 1, '<td valign="top">Nicely framed, though I''d prefer no lamp poles.</td>', 'Nicely framed, though I''d prefer no lamp poles.', '2002-05-26 23:59:00.000000', NULL, 1),
