(62404, 1701, 327, '<td valign="top">Yummie, they lood good enough to eat. Nice idea. Good B&amp;W.</td>', 'Yummie, they lood good enough to eat. Nice idea. Good B&W.', '2002-05-20 15:52:00.000000', NULL, 1),
