(62420, 1702, 1, '<td valign="top">The colors seem a little dull -- perhaps a brighter light could''ve whitened/brightened up the pieces.</td>', 'The colors seem a little dull -- perhaps a brighter light could''ve whitened/brightened up the pieces.', '2002-05-20 13:40:00.000000', NULL, 1),
