(62455, 1706, 1024, '<td valign="top">I think this might have been a stronger photo in color (just my opinion)  Good detail and very sharp focus in the right places.</td>', 'I think this might have been a stronger photo in color (just my opinion)  Good detail and very sharp focus in the right places.', '2002-05-24 07:47:00.000000', NULL, 1),
(62456, 1706, 255, '<td valign="top">nice DOF, good use of B&amp;W  and great depiction of "poker night!"</td>', 'nice DOF, good use of B&W  and great depiction of "poker night!"', '2002-05-24 13:11:00.000000', NULL, 1),
(62457, 1706, 1041, '<td valign="top">Good setup.  If I was to suggest changes, I would use a plain glass and not make the picture b&amp;w.  The colors of the cards and the money would''ve looked good here, I think</td>', 'Good setup.  If I was to suggest changes, I would use a plain glass and not make the picture b&w.  The colors of the cards and the money would''ve looked good here, I think', '2002-05-24 15:45:00.000000', NULL, 1),
(62458, 1706, 661, '<td valign="top">Very clear shot.  Like the reflection in the glass.</td>', 'Very clear shot.  Like the reflection in the glass.', '2002-05-24 23:17:00.000000', NULL, 1),
(62459, 1706, 543, '<td valign="top">You had some nice colors to work with here (whiskey, cards, greenbacks).  I wonder what made you decide on B/W (this from a B/W fan).  Some oversharpening shows on the cards and glass, and a little more DOF to include the logo on the glass in the field of focus would have helped since it''s near a hotspot.</td>', 'You had some nice colors to work with here (whiskey, cards, greenbacks).  I wonder what made you decide on B/W (this from a B/W fan).  Some oversharpening shows on the cards and glass, and a little more DOF to include the logo on the glass in the field of focus would have helped since it''s near a hotspot.', '2002-05-25 03:25:00.000000', NULL, 1),
(62460, 1706, 1128, '<td valign="top">Good composition.  I think I might have liked to see this in color.</td>', 'Good composition.  I think I might have liked to see this in color.', '2002-05-25 09:11:00.000000', NULL, 1),
(62461, 1706, 637, '<td valign="top">This image really gives me a feeling of being there.  B&amp;W works for me.</td>', 'This image really gives me a feeling of being there.  B&W works for me.', '2002-05-26 01:20:00.000000', NULL, 1),
(62462, 1706, 1, '<td valign="top">Nicely setup, a little more DOF could help clear up the money.  I don''t think there''s any need for it to be out of focus.</td>', 'Nicely setup, a little more DOF could help clear up the money.  I don''t think there''s any need for it to be out of focus.', '2002-05-27 00:11:00.000000', NULL, 1),
